CREATE TABLE public.regional_configuration (state_code text PRIMARY KEY, configuration jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.regional_configuration TO authenticated; GRANT ALL ON public.regional_configuration TO service_role;
ALTER TABLE public.regional_configuration ENABLE ROW LEVEL SECURITY;
CREATE POLICY regional_master_read ON public.regional_configuration FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.platform_master_admin WHERE user_id=auth.uid()));
ALTER TABLE public.provider_network_profiles ADD COLUMN regional_service_areas jsonb;
ALTER TABLE public.user_portal_preferences ADD COLUMN home_state text;
ALTER TABLE public.ride_requests ADD COLUMN pickup_state text, ADD COLUMN dropoff_state text, ADD COLUMN pickup_county text, ADD COLUMN dropoff_county text, ADD COLUMN pickup_timezone text, ADD COLUMN dropoff_timezone text, ADD COLUMN regional_evidence jsonb;
ALTER TABLE public.trips ADD COLUMN pickup_state text, ADD COLUMN dropoff_state text, ADD COLUMN pickup_county text, ADD COLUMN dropoff_county text, ADD COLUMN pickup_timezone text, ADD COLUMN dropoff_timezone text, ADD COLUMN regional_evidence jsonb;
ALTER TABLE public.trip_distributions ADD COLUMN pickup_state text, ADD COLUMN destination_state text, ADD COLUMN destination_timezone text;
CREATE FUNCTION public.us_state_catalog() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT jsonb_object_agg(split_part(v,':',1),jsonb_build_object('name',split_part(v,':',2),'country','US','status',CASE WHEN split_part(v,':',1)='FL' THEN 'publicly_active' ELSE 'inactive' END)) FROM unnest(string_to_array('AL:Alabama|AK:Alaska|AZ:Arizona|AR:Arkansas|CA:California|CO:Colorado|CT:Connecticut|DE:Delaware|DC:District of Columbia|FL:Florida|GA:Georgia|HI:Hawaii|ID:Idaho|IL:Illinois|IN:Indiana|IA:Iowa|KS:Kansas|KY:Kentucky|LA:Louisiana|ME:Maine|MD:Maryland|MA:Massachusetts|MI:Michigan|MN:Minnesota|MS:Mississippi|MO:Missouri|MT:Montana|NE:Nebraska|NV:Nevada|NH:New Hampshire|NJ:New Jersey|NM:New Mexico|NY:New York|NC:North Carolina|ND:North Dakota|OH:Ohio|OK:Oklahoma|OR:Oregon|PA:Pennsylvania|RI:Rhode Island|SC:South Carolina|SD:South Dakota|TN:Tennessee|TX:Texas|UT:Utah|VT:Vermont|VA:Virginia|WA:Washington|WV:West Virginia|WI:Wisconsin|WY:Wyoming','|')) v $$;
CREATE FUNCTION public.us_regional_readiness() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_master_admin WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Master Admin required';END IF; SELECT jsonb_agg(jsonb_build_object('code',s.key,'name',s.value->>'name','status',CASE WHEN s.key='FL' THEN 'publicly_active' ELSE coalesce(c.configuration->>'status','inactive') END,'configuration',coalesce(c.configuration,'{}'),'timezone_supported',true,'legacy_florida',s.key='FL')) INTO result FROM jsonb_each(public.us_state_catalog()) s LEFT JOIN public.regional_configuration c ON c.state_code=s.key;RETURN result;END $$;
CREATE FUNCTION public.save_regional_configuration(_state text,_configuration jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_master_admin WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Master Admin required';END IF;IF NOT public.us_state_catalog() ? _state OR length(trim(_reason))<10 OR _state='FL' OR coalesce(_configuration->>'status','') NOT IN ('inactive','foundation_only') OR jsonb_typeof(_configuration) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Only inactive regional foundations may be configured; Florida and activation are protected';END IF;INSERT INTO public.regional_configuration(state_code,configuration,updated_by) VALUES(_state,_configuration,auth.uid()) ON CONFLICT(state_code) DO UPDATE SET configuration=excluded.configuration,updated_by=auth.uid(),updated_at=now();INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'regional_configuration_changed','saved',jsonb_build_object('state',_state,'reason',_reason,'configuration',_configuration));END $$;
CREATE FUNCTION public.save_home_state(_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.us_state_catalog() ? _state OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Valid state and sign in required';END IF;INSERT INTO public.user_portal_preferences(user_id,home_state) VALUES(auth.uid(),_state) ON CONFLICT(user_id) DO UPDATE SET home_state=excluded.home_state;INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'regional_preference_changed','saved',jsonb_build_object('state',_state,'eligibility_changed',false));END $$;
CREATE FUNCTION public.save_regional_service_areas(_ws uuid,_areas jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb;BEGIN IF NOT public.network_workspace_access(_ws,true) OR NOT public.can_manage_account_connections(_ws) THEN RAISE EXCEPTION 'Provider manager required';END IF;IF jsonb_typeof(_areas->'areas') IS DISTINCT FROM 'array' OR jsonb_array_length(_areas->'areas')>100 OR jsonb_typeof(_areas->'crossState') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid service-area configuration';END IF;FOR a IN SELECT value FROM jsonb_array_elements(_areas->'areas') LOOP IF NOT public.us_state_catalog() ? (a->>'state') OR a->>'country' IS DISTINCT FROM 'US' OR coalesce(a->>'evidence','') NOT IN ('provider_entered','user_selected','generalized','approximate','unverified') OR coalesce(a->>'countyType','') NOT IN ('county','parish','borough','census_area','independent_city','municipality','district','other') OR length(coalesce(a->>'countyEquivalent',''))>120 OR length(coalesce(a->>'locality',''))>100 OR (coalesce(a->>'postalCode','')<>'' AND a->>'postalCode' !~ '^\d{5}(-\d{4})?$') OR (coalesce(a->>'timezone','')<>'' AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=a->>'timezone')) OR (coalesce(a->>'region','')<>'' AND (a->>'state'<>'FL' OR a->>'region' NOT IN ('panhandle','northeast','north-central','central','tampa-bay','southwest','southeast'))) THEN RAISE EXCEPTION 'Invalid or unconfigured service geography';END IF;END LOOP;IF _areas->>'radius' IS NOT NULL AND (_areas->>'radius')::integer NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Invalid radius';END IF;UPDATE public.provider_network_profiles SET regional_service_areas=_areas,updated_by=auth.uid(),updated_at=now() WHERE workspace_id=_ws;IF NOT FOUND THEN RAISE EXCEPTION 'Save existing service profile first';END IF;INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,details) VALUES(_ws,'regional_service_areas_changed',auth.uid(),jsonb_build_object('crossState',_areas->'crossState','count',jsonb_array_length(_areas->'areas'),'evidence','provider_entered'));END $$;
CREATE FUNCTION public.copy_request_regional_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ride_requests;BEGIN IF NEW.ride_request_id IS NOT NULL THEN SELECT * INTO r FROM public.ride_requests WHERE id=NEW.ride_request_id;NEW.pickup_state:=r.pickup_state;NEW.dropoff_state:=r.dropoff_state;NEW.pickup_county:=r.pickup_county;NEW.dropoff_county:=r.dropoff_county;NEW.pickup_timezone:=r.pickup_timezone;NEW.dropoff_timezone:=r.dropoff_timezone;NEW.regional_evidence:=r.regional_evidence;END IF;RETURN NEW;END $$;
CREATE TRIGGER copy_new_trip_regional_fields BEFORE INSERT ON public.trips FOR EACH ROW EXECUTE FUNCTION public.copy_request_regional_fields();
CREATE FUNCTION public.validate_request_regional_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.pickup_state IS NOT NULL AND NOT public.us_state_catalog() ? NEW.pickup_state) OR (NEW.dropoff_state IS NOT NULL AND NOT public.us_state_catalog() ? NEW.dropoff_state) THEN RAISE EXCEPTION 'Invalid selected state';END IF;IF (NEW.pickup_timezone IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.pickup_timezone)) OR (NEW.dropoff_timezone IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.dropoff_timezone)) THEN RAISE EXCEPTION 'Invalid IANA timezone';END IF;IF NEW.regional_evidence IS NOT NULL THEN NEW.regional_evidence:=jsonb_build_object('state','user_selected','county','user_selected','timezone','user_selected','review_required',true);END IF;RETURN NEW;END $$;
CREATE TRIGGER validate_new_request_regional_fields BEFORE INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_regional_fields();
CREATE OR REPLACE FUNCTION public.pilot_local_instant(_date date,_time time,_zone text) RETURNS timestamptz LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE base timestamptz;n integer;BEGIN IF _zone IS NULL OR _zone NOT IN ('America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Anchorage','Pacific/Honolulu','America/Phoenix','America/Detroit','America/Indiana/Indianapolis','America/Indiana/Knox','America/Indiana/Tell_City','America/Kentucky/Louisville','America/Kentucky/Monticello','America/Boise','America/Juneau','America/Nome','America/Sitka','America/Yakutat','America/Adak','America/Metlakatla','America/North_Dakota/Center','America/North_Dakota/New_Salem','America/North_Dakota/Beulah','America/Indiana/Marengo','America/Indiana/Petersburg','America/Indiana/Vevay','America/Indiana/Vincennes','America/Indiana/Winamac','America/Puerto_Rico','Pacific/Guam','Pacific/Pago_Pago','Pacific/Saipan','America/St_Thomas') OR _date IS NULL OR _time IS NULL THEN RETURN NULL;END IF;base:=(_date+_time) AT TIME ZONE _zone;SELECT count(*) INTO n FROM generate_series(base-interval '3 hours',base+interval '3 hours',interval '30 minutes') x WHERE x AT TIME ZONE _zone=_date+_time;IF n<>1 THEN RETURN NULL;END IF;RETURN base;END $$;
REVOKE ALL ON FUNCTION public.us_regional_readiness(),public.save_regional_configuration(text,jsonb,text),public.save_home_state(text),public.save_regional_service_areas(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.us_regional_readiness(),public.save_regional_configuration(text,jsonb,text),public.save_home_state(text),public.save_regional_service_areas(uuid,jsonb) TO authenticated;
COMMENT ON TABLE public.regional_configuration IS 'Inactive nationwide regional foundations and requirement categories; not legal approval or activation. States without approved evidence are ineligible. Florida remains in retained configuration.';